import {esc} from './weather-tools.js';
export function createSchools(ctx){
 let generation=0,timer=0,questionId=null,questionPlace='',lastNotice='',pushConfig=null,loading=false;
 const $=s=>document.querySelector(s),key=()=>JSON.stringify(ctx.get().place),date=s=>new Date(s+'T12:00:00Z').toLocaleDateString('it-IT',{day:'numeric',month:'long'});
 const warning='Risposta della community, non un’ordinanza ufficiale. Controlla il sito del Comune.';
 function page(){return `<section><h1>Scuole e allerte</h1><div data-atmo-alert>${ctx.alertHTML()}</div><p>Le scuole non chiudono automaticamente con l’allerta. Decide il sindaco: controlla il sito del tuo Comune.</p><div id="school-status" role="status">Controllo le domande della zona…</div><div id="school-ask"></div><div class="actions"><button id="school-nearby">Sono qui: mostra le domande vicine</button><button id="school-refresh">Aggiorna risposte</button></div><p class="small">La posizione viene richiesta solo al tuo tocco e salvata come zona approssimata. La presenza vale 10 minuti; le domande scadono dopo 2 ore. Comuni vicini possono decidere diversamente.</p><div id="school-questions" aria-live="polite"></div><div id="school-push"></div><a href="#regole">Regole della community</a></section>`}
 async function position(){if(!navigator.geolocation)throw Error('Posizione non disponibile. Puoi leggere le risposte alle tue domande.');return new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(p=>resolve({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,locatedAt:p.timestamp,consent:true}),()=>reject(Error('Posizione non condivisa. Puoi comunque leggere le risposte alle tue domande.')),{enableHighAccuracy:true,maximumAge:0,timeout:15000}))}
 const status=s=>{if($('#school-status'))$('#school-status').textContent=s};
 async function load(){if(loading)return;loading=true;const run=generation,placeKey=key();try{await ctx.api('sky/session',{});const p=ctx.get().place;const [mine,nearby,alert,config]=await Promise.all([ctx.api('questions/mine'),ctx.api('questions/nearby'),ctx.api('atmosphere/safety?'+new URLSearchParams({lat:p.latitude,lon:p.longitude})),ctx.api('answer-push/config')]);if(run!==generation||!$('#school-questions')||key()!==placeKey)return;pushConfig=config;
 const active=['CAUTION','EMERGENCY'].includes(alert.mode)&&alert.level>0;
 $('#school-ask').innerHTML=active?`<button class="button" id="school-create">Qualcuno sa se domani le scuole sono chiuse a ${esc(p.name)}?</button>`:`<p>${alert.mode==='UNKNOWN'?'Non possiamo verificare il bollettino adesso. Consulta la fonte ufficiale.':'Le domande sulle scuole si aprono solo con un’allerta attiva verificata.'}</p>`;
 $('#school-create')?.addEventListener('click',ask);
 const rows=[...new Map([...mine.questions,...nearby.questions].filter(r=>!r.topic||r.topic==='school').map(r=>[r.id,r])).values()];
 $('#school-questions').innerHTML=rows.length?rows.map(r=>`<section class="card"><h2>${esc(r.city)} · scuole del ${date(r.day)}</h2><p>${r.own?'La tua domanda':'Domanda dalla zona'} · fino alle ${new Date(r.expires).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}</p><p><strong>${warning}</strong></p>${r.answers.length?r.answers.map(a=>`<div><p><strong>${esc(a.answer)}</strong> · ${new Date(a.created).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}</p>${a.url?`<a href="${esc(a.url)}" target="_blank" rel="noopener noreferrer nofollow">Link fornito dalla community: ${esc(new URL(a.url).hostname)} ↗</a><p class="small">Verifica comune, data e scuole interessate nel documento.</p>`:''}<button data-school-flag="${a.id}">Segnala risposta non attendibile</button></div>`).join(''):'<p>Nessuna risposta per ora. Non significa che le scuole siano aperte.</p>'}${!r.own?`<button data-school-answer="${r.id}">Rispondi per questo comune</button>`:''}</section>`).join(''):'<p>Nessuna domanda disponibile. Puoi chiedere per il comune selezionato quando c’è un’allerta attiva.</p>';
 document.querySelectorAll('[data-school-answer]').forEach(b=>b.onclick=()=>answer(rows.find(r=>r.id===b.dataset.schoolAnswer)));
 document.querySelectorAll('[data-school-flag]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await ctx.api('questions/answers/'+b.dataset.schoolFlag+'/flag',{});ctx.toast('Risposta oscurata e inviata alla moderazione.');await load()}catch(e){ctx.toast(e.message);b.disabled=false}});
 status(nearby.locationRequired?'Le tue domande sono disponibili. Per rispondere a quelle vicine, condividi la posizione con “Sono qui”.':'Domande entro circa 5 km dalla posizione condivisa.');paintPush();
 const notices=await ctx.api('questions/notifications');for(const n of notices.notifications)if(rows.some(r=>r.own&&r.id===n.question))await ctx.api('questions/seen',{id:n.id});$('#school-notice')?.remove();try{navigator.clearAppBadge?.()?.catch?.(()=>{})}catch{}
 }catch(e){if(run===generation)status(e.message)}finally{loading=false}}
 async function ask(){const b=$('#school-create'),place=ctx.get().place,placeKey=key();b.disabled=true;if(questionPlace!==placeKey){questionId=null;questionPlace=placeKey}questionId ||=crypto.randomUUID();try{const result=await ctx.api('questions',{id:questionId,latitude:place.latitude,longitude:place.longitude,city:place.name});questionId=null;await load();if(placeKey===key())status(result.retry?'La domanda è già aperta.':result.people===0?'Nessuno ha condiviso una presenza recente entro 5 km. La domanda resta aperta per 2 ore.':result.people+' persone hanno condiviso una presenza recente entro 5 km. La domanda è disponibile per loro.')}catch(e){status(e.message);if(e.status&&e.status<500)questionId=null}finally{if(b.isConnected)b.disabled=false}}
 function answer(r){const id=crypto.randomUUID();ctx.modal('Scuole a '+r.city,`<p>Stai rispondendo per il ${date(r.day)}.</p><p>${warning}</p><label class="field"><span>Cosa sai?</span><select id="school-answer-value" required><option value="">Scegli una risposta</option><option>Chiuse</option><option>Aperte</option><option>Non si sa ancora</option></select></label><label class="field"><span>Link all’ordinanza o alla comunicazione comunale (facoltativo)</span><input id="school-answer-url" type="url" placeholder="https://…" maxlength="1200"></label><label><input id="school-town-confirm" type="checkbox"> La risposta riguarda ${esc(r.city)}, non un comune vicino.</label><p class="small">Per inviare controlleremo la posizione attuale. Non mostreremo chi sei né le tue coordinate.</p>`,async()=>{if(!$('#school-town-confirm').checked){ctx.toast('Conferma il comune a cui si riferisce la risposta.');return false}const answer=$('#school-answer-value').value,url=$('#school-answer-url').value.trim(),p=await position();await ctx.api('questions/'+r.id+'/answers',{...p,id,answer,url,sameTown:true});try{navigator.vibrate?.(18)}catch{}ctx.toast('Risposta inviata. Ricorda: decide il Comune.');await load()})}
 async function pushRegistration(){const reg=await navigator.serviceWorker.ready;await reg.update();const candidate=reg.installing||reg.waiting;if(candidate&&candidate.state!=='activated')await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{candidate.removeEventListener('statechange',check);reject(Error('Ricarica l’app per completare l’aggiornamento.'))},15000);function check(){if(candidate.state==='installed')candidate.postMessage({type:'ACTIVATE_SCHOOL_PUSH'});if(candidate.state==='activated'){clearTimeout(timeout);candidate.removeEventListener('statechange',check);resolve()}if(candidate.state==='redundant'){clearTimeout(timeout);candidate.removeEventListener('statechange',check);reject(Error('Aggiornamento non disponibile.'))}}candidate.addEventListener('statechange',check);check()});return reg}
 function paintPush(){const host=$('#school-push');if(!host||!pushConfig)return;if(!pushConfig.eligible){host.innerHTML='<p>Le risposte sono consultabili qui. Gli avvisi si possono attivare dopo la prima segnalazione del cielo.</p>';return}if(!pushConfig.available||!('PushManager'in window)||!('serviceWorker'in navigator)||!('Notification'in window)){host.innerHTML='<p>Notifiche non disponibili in questo browser. Le risposte restano nell’app. Su iPhone può essere necessario installare l’app nella schermata Home.</p>';return}if(pushConfig.enabled){host.innerHTML='<p>Avvisi per la prima risposta attivi. Massimo 2 al giorno, solo tra le 7 e le 22 (ora italiana).</p><button id="school-push-off">Disattiva avvisi sulle risposte</button>';$('#school-push-off').onclick=async()=>{try{await ctx.api('answer-push/disable',{});pushConfig.enabled=false;paintPush()}catch(e){ctx.toast(e.message)}};return}if(pushConfig.later>Date.now()){host.innerHTML='<p>Avvisi rimandati. Puoi leggere qui le risposte alle tue domande.</p>';return}host.innerHTML='<h2>Ti avvisiamo alla prima risposta</h2><p>Solo per le tue domande. Mai pubblicità, massimo 2 avvisi al giorno, nessuno tra le 22 e le 7. Puoi continuare senza attivarli.</p><button id="school-push-on">Va bene</button> <button id="school-push-later">Non ora</button>';
 $('#school-push-later').onclick=async()=>{try{await ctx.api('answer-push/later',{});pushConfig.later=Date.now()+604800000;paintPush()}catch(e){ctx.toast(e.message)}};
 $('#school-push-on').onclick=async e=>{const button=e.currentTarget;button.disabled=true;try{const permission=await Notification.requestPermission();if(permission!=='granted'){await ctx.api('answer-push/later',{});pushConfig.later=Date.now()+604800000;paintPush();return}const reg=await pushRegistration();const bytes=Uint8Array.from(atob(pushConfig.publicKey.replaceAll('-','+').replaceAll('_','/')),c=>c.charCodeAt(0));const sub=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes});await ctx.api('answer-push/subscribe',{endpoint:sub.endpoint});pushConfig.enabled=true;paintPush()}catch(e){ctx.toast('Non è stato possibile attivare gli avvisi. Puoi leggere qui le risposte.');button.disabled=false}};
 }
 async function poll(){if(document.hidden)return;if(ctx.get().route==='scuole'){await load();return}try{const data=await ctx.api('questions/notifications');const n=data.notifications[0];if(!n||n.id===lastNotice)return;lastNotice=n.id;if(ctx.get().route==='scuole'){await load();return}let banner=$('#school-notice');if(!banner){banner=document.createElement('aside');banner.id='school-notice';banner.setAttribute('aria-live','polite');$('#main')?.prepend(banner)}banner.innerHTML=`<a href="#${n.topic&&n.topic!=='school'?'insieme':'scuole'}">È arrivata una risposta ${n.topic&&n.topic!=='school'?'sul cielo':'sulle scuole'} di ${esc(n.city)}. Leggila e controlla la fonte.</a>`;try{navigator.setAppBadge?.(data.notifications.length)?.catch?.(()=>{})}catch{}}catch{}}
 function bind(){generation++;loading=false;if(ctx.get().route==='scuole'){$('#school-refresh').onclick=()=>load();$('#school-nearby').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{await ctx.api('sky/session',{});await ctx.api('questions/presence',await position());await load()}catch(e){status(e.message)}finally{if(b.isConnected)b.disabled=false}};load()}if(!timer){timer=setInterval(poll,60000);poll()}else if(lastNotice)lastNotice='';}
 return {page,bind};
}
